using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string ImageIcon { get; set; } = string.Empty;
}

public class RecipeSubmitModel
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

public class RecipeService
{
    private readonly List<RecipeCategory> _categories;
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();
    private int _nextId;

    public RecipeService()
    {
        _categories =
        [
            new RecipeCategory { Name = "Breakfast", Description = "Start your day right with these morning favorites.", ImageIcon = "🍳" },
            new RecipeCategory { Name = "Dinner", Description = "Hearty meals for the whole family.", ImageIcon = "🍲" },
            new RecipeCategory { Name = "Desserts", Description = "Sweet treats to satisfy your cravings.", ImageIcon = "🍰" },
            new RecipeCategory { Name = "Appetizers", Description = "Perfect starters and snacks for any occasion.", ImageIcon = "🥗" },
        ];

        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "3 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Cook on a greased griddle over medium heat until bubbles form, then flip.", "Serve with maple syrup and fresh berries."],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple, healthy, and delicious avocado toast with a kick.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes", "1 egg (optional)"],
                Steps = ["Toast the sourdough bread until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread mashed avocado on the toast.", "Top with red pepper flakes and a fried egg if desired."],
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and savory Italian classic everyone loves.",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic, minced", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper", "Parmesan cheese"],
                Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, then drain excess fat.", "Sauté onion and garlic until softened.", "Add crushed tomatoes, tomato paste, and oregano. Simmer 20 minutes.", "Serve sauce over spaghetti and top with Parmesan."],
                AverageRating = 4.8, RatingCount = 22
            },
            new Recipe
            {
                Id = 4, Title = "Grilled Chicken Tacos", Category = "Dinner",
                Description = "Juicy grilled chicken tacos with fresh toppings.",
                Ingredients = ["500g chicken breast", "1 tbsp cumin", "1 tbsp chili powder", "8 small tortillas", "1 cup shredded lettuce", "1 cup diced tomatoes", "½ cup sour cream", "1 lime"],
                Steps = ["Season chicken with cumin, chili powder, salt, and pepper.", "Grill chicken until cooked through, about 6 minutes per side.", "Slice chicken into strips.", "Warm tortillas and fill with chicken, lettuce, tomatoes, and sour cream.", "Squeeze lime over the top and serve."],
                AverageRating = 4.6, RatingCount = 15
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Decadent individual cakes with a molten chocolate center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "3 egg yolks", "¼ cup sugar", "2 tbsp flour"],
                Steps = ["Preheat oven to 425°F (220°C). Grease four ramekins.", "Melt chocolate and butter together over low heat.", "Whisk eggs, egg yolks, and sugar until thick.", "Fold chocolate mixture into the eggs, then fold in flour.", "Divide batter among ramekins and bake 12–14 minutes.", "Invert onto plates and serve immediately."],
                AverageRating = 4.9, RatingCount = 30
            },
            new Recipe
            {
                Id = 6, Title = "Bruschetta", Category = "Appetizers",
                Description = "Classic Italian bruschetta with ripe tomatoes and fresh basil.",
                Ingredients = ["1 baguette, sliced", "4 ripe tomatoes, diced", "¼ cup fresh basil, chopped", "2 cloves garlic", "3 tbsp olive oil", "1 tbsp balsamic vinegar", "Salt and pepper"],
                Steps = ["Toast baguette slices until golden and rub with a garlic clove.", "Mix diced tomatoes, basil, olive oil, and balsamic vinegar.", "Season with salt and pepper.", "Spoon tomato mixture onto each toast slice.", "Serve immediately."],
                AverageRating = 4.3, RatingCount = 10
            },
            new Recipe
            {
                Id = 7, Title = "Spinach Artichoke Dip", Category = "Appetizers",
                Description = "Creamy, cheesy dip that's always a crowd pleaser.",
                Ingredients = ["200g frozen spinach, thawed and drained", "1 can artichoke hearts, chopped", "200g cream cheese", "½ cup sour cream", "1 cup shredded mozzarella", "¼ cup Parmesan", "2 cloves garlic, minced"],
                Steps = ["Preheat oven to 375°F (190°C).", "Mix all ingredients together in a bowl.", "Transfer to a baking dish.", "Bake for 25 minutes until bubbly and golden.", "Serve with tortilla chips or sliced bread."],
                AverageRating = 4.4, RatingCount = 18
            },
        ];

        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes
                .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }
    }

    public Recipe? GetRecipe(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void RateRecipe(int id, int stars)
    {
        if (stars < 1 || stars > 5) return;

        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == id);
            if (recipe is null) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
        }
    }

    public Recipe AddRecipe(RecipeSubmitModel model)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = model.Title,
                Category = model.Category,
                Description = model.Title,
                Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                AverageRating = 0,
                RatingCount = 0
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

