+@rendermode InteractiveServer
+@inject RecipeShare.Services.RecipeService RecipeService
+
+<div class="d-inline-flex align-items-center my-2">
+    @for (int i = 1; i <= 5; i++)
+    {
+        var star = i;
+        <button @onclick="() => Rate(star)"
+                style="background: none; border: none; cursor: pointer; font-size: 1.8rem; color: @(star <= displayRating ? "gold" : "#ccc"); padding: 0 2px;"
+                title="Rate @star star@(star > 1 ? "s" : "")">
+            ★
+        </button>
+    }
+    <span class="ms-2 text-muted">@currentAverage.ToString("F1") (@currentCount ratings)</span>
+</div>
+
+@code {
+    [Parameter] public int RecipeId { get; set; }
+    [Parameter] public double CurrentRating { get; set; }
+    [Parameter] public int RatingCount { get; set; }
+
+    private int displayRating;
+    private double currentAverage;
+    private int currentCount;
+
+    protected override void OnParametersSet()
+    {
+        currentAverage = CurrentRating;
+        currentCount = RatingCount;
+        displayRating = (int)Math.Round(currentAverage);
+    }
+
+    private void Rate(int stars)
+    {
+        RecipeService.RateRecipe(RecipeId, stars);
+        var updated = RecipeService.GetRecipe(RecipeId);
+        if (updated is not null)
+        {
+            currentAverage = updated.AverageRating;
+            currentCount = updated.RatingCount;
+            displayRating = (int)Math.Round(currentAverage);
+        }
+    }
+}
