     public Recipe? GetRecipe(int id)
     {
         lock (_lock)
         {
             return _recipes.FirstOrDefault(r => r.Id == id);
         }
     }

     public void RateRecipe(int id, int stars)
     {
         if (stars < 1 || stars > 5) return;

         lock (_lock)
         {
             var recipe = _recipes.FirstOrDefault(r => r.Id == id);
             if (recipe is null) return;

             var totalStars = recipe.AverageRating * recipe.RatingCount;
             recipe.RatingCount++;
             recipe.AverageRating = (totalStars + stars) / recipe.RatingCount;
         }
     }

     public Recipe AddRecipe(RecipeSubmitModel model)
     {
         lock (_lock)
         {
             var recipe = new Recipe
             {
                 Id = _nextId++,
                 Title = model.Title,
                 Category = model.Category,
                 Description = model.Title,
                 Ingredients = model.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                 Steps = model.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                 AverageRating = 0,
                 RatingCount = 0
             };
             _recipes.Add(recipe);
             return recipe;
         }
     }
